const policyMenu=document.querySelector('.menu');const policyNav=document.querySelector('.product-nav');policyMenu?.addEventListener('click',()=>{const open=policyNav.classList.toggle('open');policyMenu.setAttribute('aria-expanded',String(open))});policyNav?.addEventListener('click',event=>{if(event.target.matches('a')||event.target.closest('.nav-close')){policyNav.classList.remove('open');policyMenu.setAttribute('aria-expanded','false')}});
